2	
3	import com.example.starter.domain.Point;
4	import org.springframework.dao.EmptyResultDataAccessException;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.stereotype.Repository;
7	
8	import java.util.List;
9	
10	/**
11	 * 航线与航点数据访问。
12	 */
13	@Repository
14	public class RouteRepository {
15	
16	    private final JdbcTemplate jdbc;
17	
18	    public RouteRepository(JdbcTemplate jdbc) {
19	        this.jdbc = jdbc;
20	    }
21	
22	    /** 按 routeId 查询航线（含当前版本点列），不存在返回 null。 */
23	    public RoutePo findRoute(String routeId) {
24	        Integer version;
25	        try {
26	            version = jdbc.queryForObject(
27	                    "SELECT version FROM route WHERE route_id = ?", Integer.class, routeId);
28	        } catch (EmptyResultDataAccessException ex) {
29	            return null;
30	        }
31	        if (version == null) {
32	            return null;
33	        }
34	        List<Point> points = findPoints(routeId);
35	        return new RoutePo(routeId, version, points);
36	    }
37	
38	    /**
39	     * 在当前事务内对航线行做真实更新（touch 加一）取得行级排他锁，并读取航线（含点列）。
40	     *
41	     * <p>更新为不同的值确保 H2/MySQL 不跳过加锁；与替换操作的行更新互斥，
42	     * 保证审核读到的航线版本与点列来自一致状态。</p>
43	     *
44	     * @return 航线当前状态；航线不存在返回 null（更新 0 行）
45	     */
46	    public RoutePo findRouteForUpdate(String routeId) {
47	        int locked = jdbc.update(
48	                "UPDATE route SET touch = touch + 1 WHERE route_id = ?", routeId);
49	        if (locked == 0) {
50	            return null;
51	        }
52	        Integer version = jdbc.queryForObject(
53	                "SELECT version FROM route WHERE route_id = ?", Integer.class, routeId);
54	        if (version == null) {
55	            return null;
56	        }
57	        List<Point> points = findPoints(routeId);
58	        return new RoutePo(routeId, version, points);
59	    }
60	
61	    private List<Point> findPoints(String routeId) {
62	        return jdbc.query(
63	                "SELECT x, y FROM route_point WHERE route_id = ? ORDER BY seq",
64	                (rs, n) -> new Point(rs.getInt("x"), rs.getInt("y")), routeId);
65	    }
66	
67	    /** 创建航线（初始版本 1）并写入点列（调用方负责事务）。 */
68	    public void insertRoute(String routeId, List<Point> points) {
69	        jdbc.update("INSERT INTO route (route_id, version, touch) VALUES (?, 1, 0)", routeId);
70	        insertPoints(routeId, points);
71	    }
72	
73	    /**
74	     * 条件更新航线版本：仅当当前版本等于 expectedVersion 时加一（同时推进 touch
75	     * 以持有行写锁，与审核事务互斥）。
76	     *
77	     * @return 更新行数；0 表示版本不匹配
78	     */
79	    public int compareAndIncrementVersion(String routeId, int expectedVersion) {
80	        return jdbc.update(
81	                "UPDATE route SET version = version + 1, touch = touch + 1 "
82	                        + "WHERE route_id = ? AND version = ?",
83	                routeId, expectedVersion);
84	    }
85	
86	    /** 删除航线旧点列（调用方负责事务）。 */
87	    public void deletePoints(String routeId) {
88	        jdbc.update("DELETE FROM route_point WHERE route_id = ?", routeId);
89	    }
90	
91	    /** 批量写入航线点列（调用方负责事务）。 */
92	    public void insertPoints(String routeId, List<Point> points) {
93	        int seq = 0;
94	        for (Point p : points) {
95	            jdbc.update("INSERT INTO route_point (route_id, seq, x, y) VALUES (?, ?, ?, ?)",
96	                    routeId, seq++, p.x(), p.y());
97	        }
98	    }
99	}
