import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 预测气象条目（UTC，左闭右开 [validFrom, validTo)）。
 *
 * @param zoneId          预测区域标识（须已存在）
 * @param validFrom       预测时段起点（含），epoch 毫秒（UTC）
 * @param validTo         预测时段终点（不含），epoch 毫秒（UTC），必须大于起点
 * @param visibilityMeters 预测能见度，单位米，必须 >= 0
 * @param cloudBaseMeters  预测云底，单位米，必须 >= 0
 */
public record ForecastEntryDto(
        @NotBlank @Size(max = 64) String zoneId,
        @NotNull Long validFrom,
        @NotNull Long validTo,
        @NotNull Integer visibilityMeters,
        @NotNull Integer cloudBaseMeters) {
}

package com.example.starter.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 预测气象上传请求。每次上传生成一个新的预测版本，版本内记录不可变。
 * 任一条目区域不存在、时段退化、数值为负或同区域时段重叠都返回 422/404，
 * 整批不写入。
 *
 * @param entries   预测条目集合（至少一条）
 * @param operator  操作者标识，参与幂等指纹
 * @param requestId 写操作全局唯一请求标识，用于幂等重放
 */
public record ForecastUploadRequest(
        @NotNull @Valid @Size(min = 1, max = 500) List<ForecastEntryDto> entries,
        @NotBlank @Size(max = 64) String operator,
        @NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.api.dto;

/**
 * 预测气象上传结果。
 *
 * @param forecastVersion 本次上传生成的预测气象版本
 * @param entryCount      本次上传的条目数量
 */
public record ForecastUploadResult(Long forecastVersion, Integer entryCount) {
}

package com.example.starter.api.dto;

import java.util.List;

/**
 * 预测气象版本明细查询结果。
 *
 * @param forecastVersion 预测气象版本
 * @param entryCount      条目数量
 * @param entries         预测条目（按 zoneId、时段起点升序，稳定排序）
 */
public record ForecastVersionDto(
        Long forecastVersion,
        Integer entryCount,
        List<ForecastEntryDto> entries) {
}

