        List<ReviewResultDto> history = service.getRouteReviews("r1");
        assertEquals(2, history.size());
        // 倒序（最新在前），每条保留原结论
        assertEquals(dataOf(second).reviewId(), history.get(0).reviewId());
        assertEquals("CLEAR", history.get(0).conclusion());
        assertEquals(dataOf(first).reviewId(), history.get(1).reviewId());
        assertEquals("BLOCKED", history.get(1).conclusion());
        assertNull(history.get(0).current());

        // 诊断对不存在的审核 → 404
